begin;
create temporary table four_ids(label text primary key,id uuid default gen_random_uuid());insert into four_ids(label) values('tape'),('pat'),('outsider');grant select on four_ids to authenticated;
insert into auth.users(id) select id from four_ids;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from four_ids where label='tape'),true);select public.complete_onboarding('Four Tape','เงินรวม',10000);
select set_config('request.jwt.claim.sub',(select id::text from four_ids where label='pat'),true);select public.complete_onboarding('Four Pat','เงินรวม',20000);
reset role;
insert into moneyspace_private.comparison_links(user_a,user_b,share_a,share_b) select a.id,b.id,true,true from four_ids a cross join four_ids b where a.label='tape' and b.label='pat';
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from four_ids where label='pat'),true);
do $$declare c uuid;tx uuid;s jsonb;g uuid;m date:=date_trunc('month',timezone('Asia/Bangkok',now()))::date;today date:=timezone('Asia/Bangkok',now())::date;begin
 insert into public.categories(owner_id,name,icon,default_tag) values(auth.uid(),'อาหารและเครื่องดื่ม','🍽️','need') returning id into c;
 tx:=(public.moneyspace_write('add_transaction',jsonb_build_object('kind','expense','amount','100','category_id',c,'merchant','PRIVATE MERCHANT','notes','PRIVATE NOTE','date',today),gen_random_uuid())->>'id')::uuid;
 perform public.moneyspace_write('add_transaction',jsonb_build_object('kind','refund','amount','20','refund_of_id',tx,'date',today),gen_random_uuid());
 g:=(public.moneyspace_write('create_goal',jsonb_build_object('name','Goal','amount','5000'),gen_random_uuid())->>'id')::uuid;
 perform public.moneyspace_write('earmark_goal',jsonb_build_object('goal_id',g,'amount','2000'),gen_random_uuid());
 s:=public.moneyspace_comparison(m);
 if (s->>'details_ready')::boolean or exists(select 1 from jsonb_array_elements(s->'people') rowdata where rowdata?'categories' or rowdata?'total_money') then raise exception 'FAIL: original consent broadened';end if;
 if exists(select 1 from jsonb_array_elements(s->'people') p where jsonb_array_length(p->'recent_daily')<>7) or s->>'recent_from'<>(today-6)::text or s->>'recent_through'<>today::text then raise exception 'FAIL: rolling window';end if;
 perform public.moneyspace_comparison_details(true,(s->>'version')::timestamptz);
 if (public.moneyspace_comparison(m)->>'details_ready')::boolean then raise exception 'FAIL: unilateral detail sharing';end if;
end $$;
select set_config('request.jwt.claim.sub',(select id::text from four_ids where label='tape'),true);
do $$declare s jsonb;p jsonb;v timestamptz;m date:=date_trunc('month',timezone('Asia/Bangkok',now()))::date;today date:=timezone('Asia/Bangkok',now())::date;begin
 s:=public.moneyspace_comparison(m);v:=(s->>'version')::timestamptz;perform public.moneyspace_comparison_details(true,v);perform public.moneyspace_comparison_details(true,v);
 s:=public.moneyspace_comparison(m);
 select x into p from jsonb_array_elements(s->'people') x where x->>'key'='pat';
 if (p->>'total_money')::numeric<>19920 then raise exception 'FAIL: savings double counted: %',p;end if;
 if jsonb_array_length(p->'categories')<>1 or p->'categories'->0->>'name'<>'อาหารและเครื่องดื่ม' or (p->'categories'->0->>'net')::numeric<>80 then raise exception 'FAIL: category forced split or wrong refund';end if;
 if s::text like '%PRIVATE MERCHANT%' or s::text like '%PRIVATE NOTE%' then raise exception 'FAIL: raw detail leak';end if;
 s:=public.moneyspace_comparison((m-interval '1 month')::date);
 select x into p from jsonb_array_elements(s->'people') x where x->>'key'='pat';
 if jsonb_array_length(p->'categories')<>0 or (p->>'total_money')::numeric<>19920 or (select sum((x->>'net')::numeric) from jsonb_array_elements(p->'recent_daily') x)<>80 or s->>'recent_through'<>today::text then raise exception 'FAIL: historical month corrupted independent current views';end if;
 perform public.moneyspace_comparison_details(false,(s->>'version')::timestamptz);
 s:=public.moneyspace_comparison(m);
 if exists(select 1 from jsonb_array_elements(s->'people') rowdata where rowdata?'categories' or rowdata?'total_money') or s->>'status'<>'ready' then raise exception 'FAIL: extra revocation should hide details, retain basic graph';end if;
end $$;
select set_config('request.jwt.claim.sub',(select id::text from four_ids where label='outsider'),true);
do $$begin begin perform public.moneyspace_comparison_details(true,now());raise exception 'FAIL: outsider enabled details';exception when insufficient_privilege then null;end;end $$;
reset role;set local role anon;
do $$begin begin perform public.moneyspace_comparison_details(true,now());raise exception 'FAIL: anon details';exception when insufficient_privilege then null;end;end $$;
reset role;
rollback;
